def link_records(apps, schema_editor):
    """Gives each record a BatchRecord for its batch, in the batch's payload order."""
    batch_record = apps.get_model("clinvar_submission_service", "BatchRecord")
    record = apps.get_model("clinvar_submission_service", "Record")
    for row in record.objects.exclude(batch=None).select_related("batch"):
        local_ids = [
            item.get("localID") for item in row.batch.payload["germlineSubmission"]
        ]
        batch_record.objects.create(
            batch=row.batch, record=row, position=local_ids.index(row.local_id)
        )


